mapper.select:
SELECT COUNT(*)
FROM manga_external_login_session
WHERE provider = #{provider}
  AND provider_scene_key = #{sceneKey}
  AND status = #{status}
  AND expires_at > CURRENT_TIMESTAMP

mapper.update:
UPDATE manga_external_login_session
SET status = #{confirmedStatus},
    user_id = #{userId},
    updated_by = #{actor}
WHERE provider = #{provider}
  AND provider_scene_key = #{sceneKey}
  AND status = #{waitingStatus}
  AND expires_at > CURRENT_TIMESTAMP

UPDATE manga_external_login_session
SET status = #{consumedStatus},
    consumed_at = CURRENT_TIMESTAMP,
    updated_by = #{actor}
WHERE login_token = #{loginToken}
  AND status = #{confirmedStatus}

UPDATE manga_external_login_session
SET status = #{expiredStatus},
    updated_by = #{actor}
WHERE login_token = #{loginToken}
  AND status = #{waitingStatus}
  AND expires_at <= CURRENT_TIMESTAMP
